using System;
using System.Collections.Generic;
using System.Drawing;
using System.Threading;
using Microsoft.Win32.SafeHandles;

namespace ControlCenterK
{
    /// <summary>
    /// Réglage SteelSeries : commande + valeur encodée (même description des modèles que le projet rivalcfg).
    /// Kind : range, choice, range_choice, multi_range, multi_choice, multi_choice_xy, rgb.
    /// </summary>
    sealed class SsSetting
    {
        public readonly string Label, Kind;
        public readonly byte[] Cmd, Suffix;
        public readonly int Pkt;
        public int[] In, Out, Choices;   // Choices : paires entrée, sortie
        public int Len = 1, First, Max = 1;
        public bool Flag;
        public string Xy = "";

        public SsSetting(string kind, byte[] cmd, byte[] suffix, int pkt) : this("", kind, cmd, suffix, pkt) { }

        public SsSetting(string label, string kind, byte[] cmd, byte[] suffix, int pkt)
        {
            Label = label;
            Kind = kind;
            Cmd = cmd ?? new byte[0];
            Suffix = suffix ?? new byte[0];
            Pkt = pkt;
        }

        public bool Multi { get { return Kind.StartsWith("multi"); } }

        public int MinIn { get { return Choices != null ? Choices[0] : In[0]; } }
        public int MaxIn { get { return Choices != null ? Choices[Choices.Length - 2] : In[1]; } }
        public int StepIn { get { return Choices != null ? (Choices.Length > 2 ? Choices[2] - Choices[0] : 100) : In[2]; } }

        /// <summary>Valeurs d'entrée possibles (fréquences d'une liste de choix).</summary>
        public int[] Keys()
        {
            if (Choices == null) return new int[0];
            var k = new int[Choices.Length / 2];
            for (int i = 0; i < k.Length; i++) k[i] = Choices[i * 2];
            return k;
        }

        /// <summary>Valeur à envoyer pour une entrée (DPI ou fréquence).</summary>
        int One(int v)
        {
            if (Choices != null)
            {
                int best = 0, delta = int.MaxValue;
                for (int i = 0; i < Choices.Length; i += 2)
                {
                    int d = Math.Abs(Choices[i] - v);
                    if (d < delta) { delta = d; best = Choices[i + 1]; }
                }
                return best;
            }
            int start = In[0], stop = In[1], step = In[2], m;
            if (v <= start) m = start;
            else if (v >= stop) m = stop;
            else
            {
                int delta = (v - start) % step;
                m = delta == 0 ? v : delta < step / 2.0 ? v - delta : v - delta + step;
            }
            return Out[0] + (m - start) / step * Out[2];
        }

        static void Le(List<byte> o, int v, int len)
        {
            for (int i = 0; i < len; i++) o.Add((byte)(v >> (8 * i)));
        }

        /// <summary>Paquet complet : commande + valeur(s) + suffixe.</summary>
        byte[] Packet(List<byte> value)
        {
            var o = new List<byte>(Cmd);
            o.AddRange(value);
            o.AddRange(Suffix);
            while (Pkt > 0 && o.Count < Pkt) o.Add(0);
            return o.ToArray();
        }

        public byte[] Value(int v)
        {
            var o = new List<byte>();
            Le(o, One(v), Len);
            return Packet(o);
        }

        /// <summary>Plusieurs étapes DPI ; "selected" = position de l'étape en cours dans la liste.</summary>
        public byte[] Presets(IList<int> dpis, int selected)
        {
            var o = new List<byte>();
            int n = Math.Min(dpis.Count, Max);
            o.Add((byte)(Flag ? 0xFF >> (8 - n) : n));
            o.Add((byte)(selected + First));
            if (Xy == "xxyy")
            {
                for (int axis = 0; axis < 2; axis++)
                    for (int i = 0; i < Max; i++) Le(o, i < n ? One(dpis[i]) : 0, Len);
            }
            else
                for (int i = 0; i < n; i++)
                {
                    Le(o, One(dpis[i]), Len);
                    if (Xy == "xyxy") Le(o, One(dpis[i]), Len);
                }
            return Packet(o);
        }

        public byte[] Rgb(Color c) { return Packet(new List<byte> { c.R, c.G, c.B }); }
    }

    sealed class SsModel
    {
        public readonly string Name;
        public readonly int Pid, Endpoint;
        public SsSetting Dpi, Dpi2, Poll;
        public SsSetting[] Colors = new SsSetting[0];

        public SsModel(string name, int pid, int endpoint) { Name = name; Pid = pid; Endpoint = endpoint; }
    }

