        {
            this.model = model;
            this.info = info;
            this.h = h;
        }

        public static SteelSeriesMouse Probe(List<HidInfo> group)
        {
            var model = Array.Find(Models, m => m.Pid == group[0].Pid);
            if (model == null) return null;
            var ifs = group.FindAll(x => x.OutLen > 0 && (x.Interface == model.Endpoint || (x.Interface < 0 && model.Endpoint == 0)));
            ifs.Sort((a, b) => (b.UsagePage >= 0xFF00 ? 1 : 0) - (a.UsagePage >= 0xFF00 ? 1 : 0));
            foreach (var info in ifs)
            {
                var hd = Hid.Open(info.Path, true);
                if (hd.IsInvalid) { hd.Dispose(); continue; }
                var dev = new SteelSeriesMouse(model, info, hd) { Brand = "SteelSeries", Name = model.Name };
                if (model.Dpi != null) { dev.MinDpi = model.Dpi.MinIn; dev.MaxDpi = model.Dpi.MaxIn; dev.DpiStep = Math.Max(1, model.Dpi.StepIn); }
                if (model.Poll != null) dev.PollRates = model.Poll.Keys();
                var zones = new List<string>();
                foreach (var c in model.Colors) zones.Add(c.Label);
                dev.Zones = zones.ToArray();
                return dev;
            }
            return null;
        }

        bool Write(byte[] packet)
        {
            var r = new byte[packet.Length + 1]; // octet 0 : identifiant de rapport (0)
            Array.Copy(packet, 0, r, 1, packet.Length);
            lock (io)
            {
                bool ok = Hid.Write(h, r, info.OutLen);
                Thread.Sleep(50); // les souris SteelSeries n'aiment pas les commandes trop rapprochées
                return ok;
            }
        }

        public override bool SetDpi(int dpi)
        {
            var d = model.Dpi;
            if (d == null) return false;
            return Write(d.Multi ? d.Presets(new[] { dpi }, 0) : d.Value(dpi));
        }

        public override void ApplyStages(IList<DpiStage> stages, int current)
        {
            var d = model.Dpi;
            if (d == null) return;
            if (current <= 0 || current >= stages.Count) { SetDpi(stages[Math.Max(0, Math.Min(stages.Count - 1, current))].Dpi); return; }
            // étapes actives (hors sniper), en gardant l'étape en cours
            var list = new List<int>();
            int selected = 0;
            for (int i = 1; i < stages.Count && list.Count < Math.Max(1, d.Max); i++)
            {
                if (!stages[i].Enabled && i != current) continue;
                if (i == current) selected = list.Count;
                list.Add(stages[i].Dpi);
            }
            if (d.Multi) { Write(d.Presets(list, selected)); return; }
            Write(d.Value(stages[current].Dpi));
            if (model.Dpi2 != null) Write(model.Dpi2.Value(list.Count > 1 ? list[(selected + 1) % list.Count] : stages[current].Dpi));
        }

        public override void SelectStage(IList<DpiStage> stages, int stage) { ApplyStages(stages, stage); }

        public override bool SetPollRate(int hz)
        {
            return model.Poll != null && Write(model.Poll.Value(hz));
        }

        public override bool SetZones(Color[] colors)
        {
            bool ok = true;
            for (int i = 0; i < model.Colors.Length && i < colors.Length; i++) ok &= Write(model.Colors[i].Rgb(colors[i]));
            return ok;
        }

        public override bool Alive()
        {
            return Hid.Paths(null).Exists(p => string.Equals(p, info.Path, StringComparison.OrdinalIgnoreCase));
        }

        public override void Dispose() { h.Dispose(); }
    }
}
